import{_ as p,C as o,o as e,c as t,j as a,a as n,E as c,a2 as r}from"./chunks/framework.BetZR81g.js";const u=JSON.parse('{"title":"这个主页是怎么做出来的：一个强调色与几段图标变形","description":"从一版流动的极光渐变改成单色画布，只保留一个强调色；背景静态，动效集中在图标变形和微交互上。","frontmatter":{"title":"这个主页是怎么做出来的：一个强调色与几段图标变形","titleHtml":"这个主页是怎么做出来的：一个<span class=\\"nowrap\\">强调色</span>与<span class=\\"nowrap\\">几段图标变形</span>","date":"2026-10-26","category":"建站","tags":["建站","CSS","动效"],"description":"从一版流动的极光渐变改成单色画布，只保留一个强调色；背景静态，动效集中在图标变形和微交互上。","read":7,"order":3},"headers":[],"relativePath":"blog/posts/building-this-site.md","filePath":"blog/posts/building-this-site.md"}'),E={name:"blog/posts/building-this-site.md"};function y(i,s,F,d,B,h){const l=o("ArticleMeta");return e(),t("div",null,[s[0]||(s[0]=a("h1",{id:"这个主页是怎么做出来的-一个强调色与几段图标变形",tabindex:"-1"},[n("这个主页是怎么做出来的：一个"),a("span",{class:"nowrap"},"强调色"),n("与"),a("span",{class:"nowrap"},"几段图标变形"),n(),a("a",{class:"header-anchor",href:"#这个主页是怎么做出来的-一个强调色与几段图标变形","aria-label":'Permalink to "这个主页是怎么做出来的：一个<span class="nowrap">强调色</span>与<span class="nowrap">几段图标变形</span>"'},"​")],-1)),c(l),s[1]||(s[1]=r(`<blockquote><p>这篇文章写的是第一版手写主页的实现。现在站点已迁到 VitePress：文章用 Markdown 编写，侧栏和文章列表自动生成；配色、静态背景和首页结构沿用。</p></blockquote><p>这一版主页的目标很明确：保留“有动效”的感觉，但把颜色和背景收干净。最后的做法可以概括成一句话：静态的背景，单色的界面，动效只出现在需要它解释状态的地方。</p><h2 id="先收颜色-一套设计令牌" tabindex="-1">先收颜色：一套设计令牌 <a class="header-anchor" href="#先收颜色-一套设计令牌" aria-label="Permalink to &quot;先收颜色：一套设计令牌&quot;">​</a></h2><p>整站只有两组中性色加一个强调色。浅色和深色共用同一套变量名：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">:root</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#FFAB70;">  --bg</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#fafafa</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --surface</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#ffffff</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --line</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#e7e7ea</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --ink</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#18181b</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --body</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#52525b</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --mute</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#6f6f79</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --accent</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#0a5bd3</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#85E89D;">html</span><span style="color:#B392F0;">.dark</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#FFAB70;">  --bg</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#08080a</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --surface</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#0e0e11</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --line</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#232328</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --ink</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#f4f4f5</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --body</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#a1a1aa</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --mute</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#83838d</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#FFAB70;">  --accent</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">#7cb2ff</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre></div><p>强调色只出现在几个地方：标题里的半句话、区块编号、悬停状态、阅读进度和链接。其余全部是黑白灰。颜色一少，间距和字重的层级反而更清楚。</p><h2 id="背景为什么不动" tabindex="-1">背景为什么不动 <a class="header-anchor" href="#背景为什么不动" aria-label="Permalink to &quot;背景为什么不动&quot;">​</a></h2><p>之前那版主页用了四色流动渐变和毛玻璃。它确实“有动感”，但所有元素都在动，反而没有重点。现在背景只剩一层静态网格和顶部一层很淡的光晕，滚动时不会跟着晃。</p><p>这个决定来自 morphicons 的网站：它的设计注释里写着 “Static on purpose; motion lives in the morphs.” 背景是静的，动效留给图标变形。对个人主页来说，这句话很好用：背景负责氛围，动效负责反馈。</p><h2 id="图标变形怎么做" tabindex="-1">图标变形怎么做 <a class="header-anchor" href="#图标变形怎么做" aria-label="Permalink to &quot;图标变形怎么做&quot;">​</a></h2><p>第一版首页需要变形的图标不多：外链箭头、查看项目箭头、移动端菜单。每一对图标都表示成 24×24 网格上的折线点集，例如右箭头和右上箭头：</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">const</span><span style="color:#79B8FF;"> ICONS</span><span style="color:#F97583;"> =</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">  right: [</span></span>
<span class="line"><span style="color:#E1E4E8;">    [[</span><span style="color:#79B8FF;">4</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">12</span><span style="color:#E1E4E8;">], [</span><span style="color:#79B8FF;">20</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">12</span><span style="color:#E1E4E8;">]],</span></span>
<span class="line"><span style="color:#E1E4E8;">    [[</span><span style="color:#79B8FF;">13</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">5</span><span style="color:#E1E4E8;">], [</span><span style="color:#79B8FF;">20</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">12</span><span style="color:#E1E4E8;">], [</span><span style="color:#79B8FF;">13</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">19</span><span style="color:#E1E4E8;">]]</span></span>
<span class="line"><span style="color:#E1E4E8;">  ],</span></span>
<span class="line"><span style="color:#E1E4E8;">  upRight: [</span></span>
<span class="line"><span style="color:#E1E4E8;">    [[</span><span style="color:#79B8FF;">5</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">19</span><span style="color:#E1E4E8;">], [</span><span style="color:#79B8FF;">19</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">5</span><span style="color:#E1E4E8;">]],</span></span>
<span class="line"><span style="color:#E1E4E8;">    [[</span><span style="color:#79B8FF;">8</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">5</span><span style="color:#E1E4E8;">], [</span><span style="color:#79B8FF;">19</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">5</span><span style="color:#E1E4E8;">], [</span><span style="color:#79B8FF;">19</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">16</span><span style="color:#E1E4E8;">]]</span></span>
<span class="line"><span style="color:#E1E4E8;">  ]</span></span>
<span class="line"><span style="color:#E1E4E8;">};</span></span></code></pre></div><p>变形时先按弧长把每条折线重采样成相同数量的点，再逐点插值。这样不需要处理贝塞尔曲线，也不必引入图形库：两组点一一对应，中间的每一帧就是一行 <code>d</code> 字符串。</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#F97583;">function</span><span style="color:#B392F0;"> buildPath</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">a</span><span style="color:#E1E4E8;">, </span><span style="color:#FFAB70;">b</span><span style="color:#E1E4E8;">, </span><span style="color:#FFAB70;">t</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#F97583;">  let</span><span style="color:#E1E4E8;"> d </span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;"> &#39;&#39;</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#F97583;">  for</span><span style="color:#E1E4E8;"> (</span><span style="color:#F97583;">let</span><span style="color:#E1E4E8;"> s </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> 0</span><span style="color:#E1E4E8;">; s </span><span style="color:#F97583;">&lt;</span><span style="color:#E1E4E8;"> a.</span><span style="color:#79B8FF;">length</span><span style="color:#E1E4E8;">; s</span><span style="color:#F97583;">++</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#F97583;">    for</span><span style="color:#E1E4E8;"> (</span><span style="color:#F97583;">let</span><span style="color:#E1E4E8;"> i </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> 0</span><span style="color:#E1E4E8;">; i </span><span style="color:#F97583;">&lt;</span><span style="color:#E1E4E8;"> a[s].</span><span style="color:#79B8FF;">length</span><span style="color:#E1E4E8;">; i</span><span style="color:#F97583;">++</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#F97583;">      const</span><span style="color:#79B8FF;"> x</span><span style="color:#F97583;"> =</span><span style="color:#E1E4E8;"> a[s][i][</span><span style="color:#79B8FF;">0</span><span style="color:#E1E4E8;">] </span><span style="color:#F97583;">+</span><span style="color:#E1E4E8;"> (b[s][i][</span><span style="color:#79B8FF;">0</span><span style="color:#E1E4E8;">] </span><span style="color:#F97583;">-</span><span style="color:#E1E4E8;"> a[s][i][</span><span style="color:#79B8FF;">0</span><span style="color:#E1E4E8;">]) </span><span style="color:#F97583;">*</span><span style="color:#E1E4E8;"> t;</span></span>
<span class="line"><span style="color:#F97583;">      const</span><span style="color:#79B8FF;"> y</span><span style="color:#F97583;"> =</span><span style="color:#E1E4E8;"> a[s][i][</span><span style="color:#79B8FF;">1</span><span style="color:#E1E4E8;">] </span><span style="color:#F97583;">+</span><span style="color:#E1E4E8;"> (b[s][i][</span><span style="color:#79B8FF;">1</span><span style="color:#E1E4E8;">] </span><span style="color:#F97583;">-</span><span style="color:#E1E4E8;"> a[s][i][</span><span style="color:#79B8FF;">1</span><span style="color:#E1E4E8;">]) </span><span style="color:#F97583;">*</span><span style="color:#E1E4E8;"> t;</span></span>
<span class="line"><span style="color:#E1E4E8;">      d </span><span style="color:#F97583;">+=</span><span style="color:#E1E4E8;"> (i </span><span style="color:#F97583;">===</span><span style="color:#79B8FF;"> 0</span><span style="color:#F97583;"> ?</span><span style="color:#9ECBFF;"> &#39;M&#39;</span><span style="color:#F97583;"> :</span><span style="color:#9ECBFF;"> &#39;L&#39;</span><span style="color:#E1E4E8;">) </span><span style="color:#F97583;">+</span><span style="color:#E1E4E8;"> x.</span><span style="color:#B392F0;">toFixed</span><span style="color:#E1E4E8;">(</span><span style="color:#79B8FF;">2</span><span style="color:#E1E4E8;">) </span><span style="color:#F97583;">+</span><span style="color:#9ECBFF;"> &#39; &#39;</span><span style="color:#F97583;"> +</span><span style="color:#E1E4E8;"> y.</span><span style="color:#B392F0;">toFixed</span><span style="color:#E1E4E8;">(</span><span style="color:#79B8FF;">2</span><span style="color:#E1E4E8;">);</span></span>
<span class="line"><span style="color:#E1E4E8;">    }</span></span>
<span class="line"><span style="color:#E1E4E8;">  }</span></span>
<span class="line"><span style="color:#F97583;">  return</span><span style="color:#E1E4E8;"> d;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre></div><p>进度 <code>t</code> 不是固定时长的缓动，而是用弹簧积分算出来的：</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">v </span><span style="color:#F97583;">+=</span><span style="color:#E1E4E8;"> (</span><span style="color:#79B8FF;">420</span><span style="color:#F97583;"> *</span><span style="color:#E1E4E8;"> (target </span><span style="color:#F97583;">-</span><span style="color:#E1E4E8;"> t) </span><span style="color:#F97583;">-</span><span style="color:#79B8FF;"> 30</span><span style="color:#F97583;"> *</span><span style="color:#E1E4E8;"> v) </span><span style="color:#F97583;">*</span><span style="color:#E1E4E8;"> dt;</span></span>
<span class="line"><span style="color:#E1E4E8;">t </span><span style="color:#F97583;">+=</span><span style="color:#E1E4E8;"> v </span><span style="color:#F97583;">*</span><span style="color:#E1E4E8;"> dt;</span></span></code></pre></div><p>420 是刚度，30 是阻尼。鼠标移开时目标变回 0，弹簧会从当前位置和当前速度继续走，所以中途打断也很自然。第一版的所有图标共用这套逻辑，只在悬停、聚焦和菜单展开时触发。</p><h2 id="阅读体验" tabindex="-1">阅读体验 <a class="header-anchor" href="#阅读体验" aria-label="Permalink to &quot;阅读体验&quot;">​</a></h2><p>第一版博客补上了几件文档站常见的事：文章列表、左侧文章栏、右侧本页目录、阅读进度条、代码复制按钮、上一篇/下一篇。它们都不是装饰，而是让长文章更好读。</p><p>目录不是手写的：页面加载后从正文里的 <code>h2</code> / <code>h3</code> 生成，滚动时高亮当前章节。代码块复制按钮也是同一套思路：只在有 <code>pre</code> 的页面出现，不污染正文结构。</p><p>迁到 VitePress 后，目录、上一篇/下一篇、代码复制和搜索变成了内置能力；文章元信息和阅读进度由一层很薄的自定义主题补上。</p><h2 id="可访问性上的几个决定" tabindex="-1">可访问性上的几个决定 <a class="header-anchor" href="#可访问性上的几个决定" aria-label="Permalink to &quot;可访问性上的几个决定&quot;">​</a></h2><ul><li><strong>键盘可达</strong>：所有交互都有 <code>:focus-visible</code> 轮廓。</li><li><strong>状态可读</strong>：导航用 <code>aria-current</code>，菜单用 <code>aria-expanded</code>，移动端菜单关闭时设为 <code>inert</code>。</li><li><strong>减弱动效</strong>：系统开启 <code>prefers-reduced-motion</code> 时，变形直接跳到终点，不做过渡。</li><li><strong>无 JS 也能读</strong>：正文默认可见，滚动显现只在 <code>html.js</code> 下才隐藏元素。</li></ul><h2 id="迁到-vitepress-之后" tabindex="-1">迁到 VitePress 之后 <a class="header-anchor" href="#迁到-vitepress-之后" aria-label="Permalink to &quot;迁到 VitePress 之后&quot;">​</a></h2><p>现在文章源文件是 <code>docs/blog/posts/*.md</code>，标题、日期、标签、摘要写在 frontmatter 里。侧栏和文章列表在构建时从这些 Markdown 里读出来，新增一篇文章不需要再同步三四个 HTML 文件。</p><p>写法变成了这样：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#79B8FF;font-weight:bold;">---</span></span>
<span class="line"><span style="color:#E1E4E8;">title: 一篇文章的标题</span></span>
<span class="line"><span style="color:#E1E4E8;">date: 2026-10-26</span></span>
<span class="line"><span style="color:#E1E4E8;">tags: [C++, Qt]</span></span>
<span class="line"><span style="color:#E1E4E8;">description: 一句话摘要</span></span>
<span class="line"><span style="color:#79B8FF;font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E1E4E8;">正文从这里开始。</span></span></code></pre></div><p>构建时运行 <code>npm run build:site</code>，VitePress 生成静态页，脚本再把产物复制到仓库根目录，GitHub Pages 继续从根目录发布。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这套站点的核心不是某个炫技效果，而是把“动”限制在少数几个地方：图标变形、滚动显现、导航高亮和阅读进度。颜色和背景越安静，这些动效越容易被注意到。</p><p>第一版是纯静态的 HTML/CSS/JS，没有构建步骤；现在用 VitePress 负责导航、搜索、目录和文章组织，设计和内容仍然保持单色、克制。写一篇新文章只需要在 <code>docs/blog/posts/</code> 放一个 Markdown 文件，侧栏和列表会自动更新。</p>`,31))])}const g=p(E,[["render",y]]);export{u as __pageData,g as default};
